import React, { useState, useEffect } from 'react';
import axios from 'axios';

const PropertyList = () => {
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  // Nayi States Modal (Popup) ke liye
  const [selectedPg, setSelectedPg] = useState(null); // Kaunsa PG khola hai
  const [showBookingForm, setShowBookingForm] = useState(false); // Form dikhana hai ya Details?
  
  // Student ke form ka data
  const [studentData, setStudentData] = useState({
    name: '', phone: '', address: '', occupation: 'Student', 
    collegeName: '', course: '', fatherName: '', motherName: '', parentPhone: ''
  });

  useEffect(() => {
    const fetchProperties = async () => {
      try {
        const response = await axios.get('http://localhost:8080/api/properties/all');
        setProperties(response.data);
        setLoading(false);
      } catch (err) {
        setError('Failed to load properties.');
        setLoading(false);
      }
    };
    fetchProperties();
  }, []);

  const handleInputChange = (e) => {
    setStudentData({ ...studentData, [e.target.name]: e.target.value });
  };

  const submitBooking = async (e) => {
    e.preventDefault();
    try {
      // Backend ko property ID, tenant ID aur baaki saari student details bhej rahe hain
      const payload = {
        propertyId: selectedPg.id,
        tenantId: 2, // Dummy for now
        studentDetails: studentData
      };
      
      const response = await axios.post('http://localhost:8080/api/bookings/request', payload);
      alert(`🎉 Badhai ho! Aapki ${selectedPg.pgName} ki booking request chali gayi hai.\n\nOwner jaldi hi aapke number ${studentData.phone} par contact karenge.`);
      
      // Popup band kar do
      closeModal();
    } catch (err) {
      alert('Error: Booking nahi ho payi. Backend check karein.');
    }
  };

  const closeModal = () => {
    setSelectedPg(null);
    setShowBookingForm(false);
  };

  const inputStyle = { width: '100%', padding: '10px', borderRadius: '6px', border: '1px solid #ccc', boxSizing: 'border-box', marginBottom: '12px' };

  if (loading) return <p style={{ textAlign: 'center' }}>Loading properties...</p>;
  if (error) return <p style={{ color: 'red', textAlign: 'center' }}>{error}</p>;

  return (
    <div style={{ marginTop: '20px', position: 'relative' }}>
      <h3 style={{ color: '#80608f', textAlign: 'center', fontSize: '2rem', marginBottom: '20px' }}>
        Available PGs & Hostels
      </h3>
      
      {/* PGs Grid */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '20px' }}>
        {properties.map((pg) => (
          <div key={pg.id} style={{ border: '1px solid #e6d9ef', borderRadius: '12px', padding: '15px', backgroundColor: '#fff', boxShadow: '0 4px 6px rgba(0,0,0,0.05)', cursor: 'pointer', transition: '0.3s' }} onClick={() => setSelectedPg(pg)}>
            <div style={{ height: '150px', backgroundColor: '#f4eff7', borderRadius: '8px', marginBottom: '15px', display: 'flex', alignItems: 'center', justifyContent: 'center', color: '#af87c8' }}>
              📸 PG Image
            </div>
            <h4 style={{ margin: '0 0 10px 0', color: '#4a4a4a', fontSize: '1.2rem' }}>{pg.pgName}</h4>
            <p style={{ margin: '5px 0' }}><strong>📍 City:</strong> {pg.city}</p>
            <p style={{ margin: '5px 0' }}><strong>💰 Rent:</strong> ₹{pg.rent}/month</p>
            <button style={{ marginTop: '15px', padding: '10px', backgroundColor: '#e6d9ef', color: '#4a3b52', border: 'none', borderRadius: '6px', width: '100%', fontWeight: 'bold' }}>
              View Details
            </button>
          </div>
        ))}
      </div>

      {/* MODAL / POPUP SCREEN */}
      {selectedPg && (
        <div style={{ position: 'fixed', top: 0, left: 0, width: '100vw', height: '100vh', backgroundColor: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000, padding: '20px', boxSizing: 'border-box' }}>
          
          <div style={{ backgroundColor: '#fff', width: '100%', maxWidth: '600px', maxHeight: '90vh', overflowY: 'auto', borderRadius: '16px', padding: '30px', position: 'relative' }}>
            
            {/* Close Button */}
            <button onClick={closeModal} style={{ position: 'absolute', top: '15px', right: '15px', background: 'none', border: 'none', fontSize: '1.5rem', cursor: 'pointer' }}>✖</button>

            {!showBookingForm ? (
              /* --- VIEW 1: PG DETAILED DETAILS --- */
              <div>
                <h2 style={{ color: '#4a3b52', marginTop: 0 }}>{selectedPg.pgName}</h2>
                <div style={{ height: '200px', backgroundColor: '#e6d9ef', borderRadius: '12px', marginBottom: '20px', backgroundImage: 'url("https://via.placeholder.com/600x200?text=PG+Room+Gallery")', backgroundSize: 'cover' }}></div>
                
                <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginBottom: '20px' }}>
                  <div style={{ background: '#f4eff7', padding: '15px', borderRadius: '8px' }}>
                    <p style={{ margin: 0 }}><strong>Rent:</strong> ₹{selectedPg.rent}/month</p>
                  </div>
                  <div style={{ background: '#f4eff7', padding: '15px', borderRadius: '8px' }}>
                    <p style={{ margin: 0 }}><strong>Sharing:</strong> {selectedPg.sharingType} Person</p>
                  </div>
                </div>

                <h4 style={{ borderBottom: '2px solid #e6d9ef', paddingBottom: '5px' }}>🌟 Amenities Provided</h4>
                <ul style={{ listStyle: 'none', padding: 0, display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                  <li>✅ {selectedPg.hasAc ? 'AC Available' : 'Non-AC'}</li>
                  <li>✅ High-Speed WiFi</li>
                  <li>✅ 3 Times Mess Food</li>
                  <li>✅ Laundry Service</li>
                  <li>✅ Attached Washroom</li>
                  <li>✅ 24/7 Power Backup</li>
                </ul>

                <h4 style={{ borderBottom: '2px solid #e6d9ef', paddingBottom: '5px', marginTop: '20px' }}>📍 Location</h4>
                <p>Located in the heart of {selectedPg.city}. Very close to main transit and college areas.</p>
                <div style={{ height: '100px', background: '#e0e0e0', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', marginBottom: '20px' }}>🗺️ Mini Map Location Preview</div>

                <button onClick={() => setShowBookingForm(true)} style={{ width: '100%', padding: '15px', backgroundColor: '#80608f', color: 'white', border: 'none', borderRadius: '8px', fontSize: '1.1rem', fontWeight: 'bold', cursor: 'pointer' }}>
                  Proceed to Book
                </button>
              </div>

            ) : (
              /* --- VIEW 2: BOOKING FORM --- */
              <div>
                <h2 style={{ color: '#4a3b52', marginTop: 0 }}>Booking Details Form</h2>
                <p style={{ color: '#666', marginBottom: '20px' }}>Please fill your details to book <b>{selectedPg.pgName}</b>.</p>
                
                <form onSubmit={submitBooking}>
                  <label>Full Name</label>
                  <input type="text" name="name" value={studentData.name} onChange={handleInputChange} required style={inputStyle} />
                  
                  <label>Phone Number</label>
                  <input type="tel" name="phone" value={studentData.phone} onChange={handleInputChange} required style={inputStyle} />
                  
                  <label>Permanent Home Address</label>
                  <textarea name="address" rows="3" value={studentData.address} onChange={handleInputChange} required style={inputStyle} />

                  <label>Current Status</label>
                  <select name="occupation" value={studentData.occupation} onChange={handleInputChange} style={inputStyle}>
                    <option value="Student">Student</option>
                    <option value="Job/Other">Job / Other</option>
                  </select>

                  {studentData.occupation === 'Student' && (
                    <div style={{ display: 'flex', gap: '10px' }}>
                      <div style={{ flex: 1 }}>
                        <label>College Name</label>
                        <input type="text" name="collegeName" value={studentData.collegeName} onChange={handleInputChange} required style={inputStyle} />
                      </div>
                      <div style={{ flex: 1 }}>
                        <label>Course</label>
                        <input type="text" name="course" value={studentData.course} onChange={handleInputChange} required style={inputStyle} />
                      </div>
                    </div>
                  )}

                  <h4 style={{ borderBottom: '2px solid #e6d9ef', paddingBottom: '5px', marginTop: '10px' }}>Parent/Guardian Details</h4>
                  
                  <div style={{ display: 'flex', gap: '10px' }}>
                    <div style={{ flex: 1 }}>
                      <label>Father's Name</label>
                      <input type="text" name="fatherName" value={studentData.fatherName} onChange={handleInputChange} required style={inputStyle} />
                    </div>
                    <div style={{ flex: 1 }}>
                      <label>Mother's Name</label>
                      <input type="text" name="motherName" value={studentData.motherName} onChange={handleInputChange} style={inputStyle} />
                    </div>
                  </div>

                  <label>Parent Phone Number</label>
                  <input type="tel" name="parentPhone" value={studentData.parentPhone} onChange={handleInputChange} required style={inputStyle} />

                  <div style={{ display: 'flex', gap: '10px', marginTop: '20px' }}>
                    <button type="button" onClick={() => setShowBookingForm(false)} style={{ flex: 1, padding: '12px', backgroundColor: '#e6d9ef', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>
                      Back
                    </button>
                    <button type="submit" style={{ flex: 2, padding: '12px', backgroundColor: '#4CAF50', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '1.1rem' }}>
                      Confirm Booking
                    </button>
                  </div>
                </form>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default PropertyList;
